const l=864e5;export function dayOfYear(t){return Math.floor((new Date(t.getFullYear(),t.getMonth(),t.getDate())-new Date(t.getFullYear(),0,1))/864e5)}export function isDaylightSaving(t){const n=new Date(t.getFullYear(),0,1).getTimezoneOffset(),o=new Date(t.getFullYear(),6,1).getTimezoneOffset();return t.getTimezoneOffset()<Math.max(n,o)}export function sunTimes(t){const o=6.1+1.3*Math.cos(2*Math.PI*(dayOfYear(t)-172)/365),e=11.95+(isDaylightSaving(t)?1:0);return{sunrise:e-o,sunset:e+o}}const r=t=>{const n=Math.min(1,Math.max(0,t));return n*n*(3-2*n)};export function mix(t,n,o){const e=Math.min(1,Math.max(0,o)),c=(s,u)=>s>>u&255,f=s=>Math.round(c(t,s)+(c(n,s)-c(t,s))*e);return f(16)<<16|f(8)<<8|f(0)}export function css(t){return`#${t.toString(16).padStart(6,"0")}`}export function lightAt(t,n=null){const o=n??t.getHours()+t.getMinutes()/60,{sunrise:e,sunset:c}=sunTimes(t),f=Math.min(r((o-e+.5)/1),r((c+.5-o)/1));let s="day";return f<=0?s="night":f<1&&(s=o<12?"dawn":"dusk"),{hour:o,daylight:f,phase:s,key:`${s}:${Math.round(f*8)}`}}const i={top:726320,bottom:2764618,sun:10466559,clouds:2895940},a={top:5208499,bottom:13483974,sun:16757611,clouds:16760732},h={top:8368861,bottom:14937327,sun:16773336,clouds:16777215};export const OFFICE_HOURS=[[0,.14],[3,.05],[4,.05],[6.5,.24],[8,.42],[17,.42],[20,.34],[24,.14]];export function officesLit(t,n=OFFICE_HOURS){const o=(t%24+24)%24;for(let e=1;e<n.length;e++){const[c,f]=n[e];if(o<=c){const[s,u]=n[e-1];return u+(f-u)*(o-s)/(c-s)}}return n[n.length-1][1]}export function lighting(t){const n=t.daylight,o=t.phase==="dawn"||t.phase==="dusk"?Math.sin(n*Math.PI):0,e=c=>mix(mix(i[c],h[c],n),a[c],o*.7);return{skyTop:e("top"),skyBottom:e("bottom"),sunColor:e("sun"),clouds:e("clouds"),sun:.12+1.4*n,hemi:.22+.7*n,fill:.12+.23*n,bounce:.06+.45*n,cityLights:1-n,offices:officesLit(t.hour),stars:r((.35-n)/.35),moonShine:1-.65*n,halo:.3+.7*o,cityNear:mix(1844019,5991293,n),cityFar:mix(2436160,8690093,n)}}
